25	/// Extract documentation comments from an attribute list.
26	pub fn documentation(attrs: &[syn::Attribute]) -> String {
27	    let mut doc = String::new();
28	
29	    // Parse doc comments.
30	    for attr in attrs {
31	        if let syn::Meta::NameValue(meta) = &attr.meta
32	            && meta.path.is_ident("doc")
33	        {
34	            if let syn::Expr::Lit(lit) = &meta.value
35	                && let syn::Lit::Str(string) = &lit.lit
36	            {
37	                let full = string.value();
38	                let line = full.strip_prefix(' ').unwrap_or(&full);
39	                doc.push_str(line);
40	                doc.push('\n');
41	            } else if let syn::Expr::Macro(expr) = &meta.value
42	                // The `stringify!` macro does not expand eagerly so we have
43	                // some very basic support for int and float expressions here.
44	                // This is e.g. used for paper sizes.
45	                && expr.mac.path.is_ident("stringify")
46	                && let Ok(lit) = syn::parse2::<syn::Lit>(expr.mac.tokens.clone())
47	                && let Some(value) = match &lit {
48	                syn::Lit::Int(int) => Some(int.base10_digits()),
49	                syn::Lit::Float(float) => Some(float.base10_digits()),
50	                _ => None,
51	            } {
52	                doc.push_str(value);
53	                doc.push('\n');
54	            }
55	        }
56	    }
57	
58	    doc.trim().into()
59	}
