240	impl Parse for BlockWithReturn {
241	    fn parse(input: ParseStream) -> Result<Self> {
242	        let mut stmts = syn::Block::parse_within(input)?;
243	        let Some(expr) = stmts.pop() else {
244	            return Err(input.error("expected at least one expression"));
245	        };
246	        Ok(Self { prefix: stmts, expr })
247	    }
