292	/// Create native function data for the function.
293	fn create_func_data(func: &Func) -> TokenStream {
294	    let Func {
295	        ident,
296	        name,
297	        title,
298	        since,
299	        docs,
300	        keywords,
301	        returns,
302	        scope,
303	        parent,
304	        constructor,
305	        contextual,
306	        ..
307	    } = func;
